import sys
import re

ASSIGN_RE = re.compile(r'^\s*([A-Za-z_]\w*)\s*<-\s*(-?\d+|[A-Za-z_]\w*)\s*;\s*$')


def main():
    text = sys.stdin.read()
    env = {}

    for raw_line in text.splitlines():
        line = raw_line.strip()
        # Skip comment lines; the "stale log" entries must not run.
        if line.startswith("//"):
            continue
        m = ASSIGN_RE.match(line)
        if not m:
            continue
        target, source = m.group(1), m.group(2)
        if re.fullmatch(r'-?\d+', source):
            value = int(source)
        else:
            value = env.get(source, 0)
        env[target] = value

    def fmt(name):
        return str(env.get(name, 0))

    print("a ?= {}; b ?= {}; TMP ?= {};".format(fmt("a"), fmt("b"), fmt("TMP")))


if __name__ == "__main__":
    main()
